import{z as i,x as B,o as A,c as d,q as E,j as s,D as r,d as l,s as o,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const f=JSON.parse('{"title":"华莱士树与进位保存","description":"","frontmatter":{"title":"华莱士树与进位保存","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/wallace-carry-save.md","filePath":"cs/wallace-carry-save.md","lastUpdated":1791063341000}'),p={name:"cs/wallace-carry-save.md"};function C(c,a,h,m,u,D){const t=B("Mermaid");return A(),d("div",null,[a[2]||(a[2]=E('<h1 id="华莱士树与进位保存" tabindex="-1">华莱士树与进位保存 <a class="header-anchor" href="#华莱士树与进位保存" aria-label="Permalink to &quot;华莱士树与进位保存&quot;">​</a></h1><div class="epigraph"><p>许多个数相加时，不必每一步都等进位走完：全加器可以先把三数压成两数，进位留到最后一次传播。</p><footer>—— 据 Wallace, A Suggestion for a Fast Multiplier, IEEE Trans. Electron. Comput. 1964；Harris and Harris, Digital Design and Computer Architecture 整理</footer></div><p><a href="/cs/booth-multiplier">上一课</a>把补码乘的部分积条数收少了，但条数仍大于 2。组成课的<a href="/cs/array-multiplier">阵列乘法</a>点到进位保留，没有把压缩树画完。缺口是：<strong>多操作数加法</strong>的延迟——若每层都用行波/CLA 把进位走完，Booth 省下的条数会被进位链吃回去。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>\\(n\\) 个已对齐的部分积要加成一个 \\(2n\\) 位积。<a href="/cs/adder-cla">CLA</a> 擅长两个数；三个以上若串成「加完再加」，每层都付一次进位传播。进位保存加法器（CSA）：一位全加器吃三比特，吐出本位和与进位，<strong>进位不链到同一层邻位</strong>，只接到下一层更高权。三数变两数（3:2 压缩）。缺口不是新的乘法语义，而是把部分积高度按对数层压到 2，再交给一次 CLA。</p><p>Wallace 树：每列独立用全加器尽量压；Dadda 树更吝啬全加器、层数策略不同。本课钉 CSA 与 Wallace 形状，不把 Dadda 的每列定额写成作业。</p><h3 id="进位保存不是「丢掉进位」" tabindex="-1">进位保存不是「丢掉进位」 <a class="header-anchor" href="#进位保存不是「丢掉进位」" aria-label="Permalink to &quot;进位保存不是「丢掉进位」&quot;">​</a></h3><p>CSA 的进位被显式保存为另一向量，最终必须与和向量做一次常规加。把 CSA 理解成近似加法，积的低位会错。它节省的是<strong>中间层的传播延迟</strong>，不是精度。</p><p><span class="marginnote">Wallace 1964 的建议是树形压缩。Harris 用 4:2 压缩器作现代积木（两个 CSA 叠成）。Hennessy/Patterson 把乘法器延迟当成整数单元的关键路径候选，不在本课展开流水线切拍。</span></p><p><span class="marginnote">常见误区：把 CSA 当成「更快的一种加法器」。它在中间层根本不做加法——只是按位重排，把三列压成两列；真正的进位传播只在最后那一次 CLA 里完成。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>部分积按权排成点图。同一权三位进一个全加器：和留本列，进位进右列（更高权）下一层。重复直到每列至多两点，再用 <a href="/cs/adder-cla">CLA</a> 收尾。4:2 压缩器把五输入（含进位入）压成和与进位，便于规则布局。</p>',12)),(A(),s(n,null,{default:r(()=>[o(t,{id:"mermaid-34",class:"mermaid",graph:"flowchart%20TD%0A%20%20PP%5B%22Booth%20%E9%83%A8%E5%88%86%E7%A7%AF%22%5D%20--%3E%20CSA%5B%223%3A2%20%2F%204%3A2%20%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20CSA%20--%3E%20TWO%5B%22%E5%92%8C%E5%90%91%E9%87%8F%20%2B%20%E8%BF%9B%E4%BD%8D%E5%90%91%E9%87%8F%22%5D%0A%20%20TWO%20--%3E%20CLA%5B%22%E6%9C%AB%E7%BA%A7%20CLA%22%5D%0A%20%20CLA%20--%3E%20LATER%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E9%99%A4%E6%B3%95%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"层数约为 \\(\\Theta(\\log_{1.5} h)\\)，\\(h\\) 是部分积高度。Booth 降低 \\(h\\)，树变浅；两者正交：编码管条数，CSA 管怎么加。",-1)),a[4]||(a[4]=e("p",null,[e("span",{class:"marginnote"},"数字实例：压 \\(h=8\\) 层部分积，串行做法要连做 7 次带进位传播的加法；CSA 只需约 \\(\\lceil\\log_{1.5} 8\\rceil = 5\\) 层压缩，再补一次 CLA——延迟从「次数 × 进位链长」变成「对数层 × 单个全加器」。")],-1)),a[5]||(a[5]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=e("p",null,"组合乘法器的关键路径 = 部分积生成 + 压缩树 + 末级 CLA。后课除法是另一条迭代或阵列通路，不共用这棵树的中间和。流水线可以把 CSA 层切开，那是时序问题，功能上仍是同一压缩。本课不把 FPGA DSP 块的内部流水线当成 CSA 的定义。",-1)),(A(),s(n,null,{default:r(()=>[o(t,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20IN3%5B%22%E5%90%8C%E4%B8%80%E5%88%97%E7%9A%84%E4%B8%89%E4%B8%AA%E6%AF%94%E7%89%B9%22%5D%20--%3E%20FA%5B%22%E4%B8%80%E4%B8%AA%E5%85%A8%E5%8A%A0%E5%99%A8%22%5D%0A%20%20FA%20--%3E%20SUM%5B%22%E5%92%8C%E4%BD%8D%3A%20%E7%95%99%E5%9C%A8%E6%9C%AC%E5%88%97%22%5D%0A%20%20FA%20--%3E%20CARRY%5B%22%E8%BF%9B%E4%BD%8D%3A%20%E7%A7%BB%E5%88%B0%E6%9B%B4%E9%AB%98%E6%9D%83%E5%88%97%22%5D%0A%20%20SUM%20--%3E%20LAYER%5B%22%E8%BF%9B%E5%85%A5%E4%B8%8B%E4%B8%80%E5%B1%82%E5%8E%8B%E7%BC%A9%22%5D%0A%20%20CARRY%20--%3E%20LAYER%0A%20%20LAYER%20--%3E%20FIN%7B%22%E6%AF%8F%E5%88%97%E8%87%B3%E5%A4%9A%E4%B8%A4%E7%82%B9%E4%BA%86%E5%90%97%3F%22%7D%0A%20%20FIN%20--%20%E5%90%A6%20--%3E%20LAYER%0A%20%20FIN%20--%20%E6%98%AF%20--%3E%20FINAL%5B%22%E6%9C%AB%E7%BA%A7%20CLA%20%E4%B8%80%E6%AC%A1%E4%BC%A0%E6%92%AD%E5%85%A8%E9%83%A8%E8%BF%9B%E4%BD%8D%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=E('<p><span class="marginnote">直觉类比：CSA 像记账只记流水不等结算——每收到三笔账先折成「小计」和「欠条」两张纸，欠条记到更右边一列；所有账目过完，最后才做一次总结算（CLA）。中间从不逐笔催款，只推迟一次清算。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不讲除法、不把浮点对阶加法器的对齐移位画进来。浮点尾数乘会再用同一棵树，但指数与规格化是后课。也不引入冗余数系的完整理论，CSA 只作为延迟手段。</p><p>后课默认：多操作数加用 CSA 压到两操作数，再一次传播进位；乘法器延迟由树深而不是 \\(h\\) 次 CLA 决定。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Booth 减少部分积；CSA/华莱士树减少中间进位传播。</li><li>3:2 把三数变成和与进位两向量；末级仍要 CLA。</li><li>不丢进位，只推迟传播。</li><li>出处：Wallace, <em>IEEE TEC</em>, 1964；Harris and Harris；Hennessy and Patterson, CA:AQA。</li></ul>',6))])}const F=i(p,[["render",C]]);export{f as __pageData,F as default};
